-- LidoRank - cluster14_asia_sud (OSM + regioni reali Natural Earth)
-- Paesi: IN, LK, MV, BD. Esegui DOPO 0016 (osm_id). Idempotente (upsert su osm_id).
on conflict (osm_id) do update set
  nome=excluded.nome, localita=excluded.localita, regione=excluded.regione,
  lat=excluded.lat, lng=excluded.lng, categoria=excluded.categoria,
  tipo=excluded.tipo, fonte=excluded.fonte, paese=excluded.paese;
